{{ config(
            materialized='table',
                post_hook={
                    "sql": "SELECT \'FLIPKART\' temp_SHOP_NAME, NULL AS awb, NULL AS CARRIER_ID, NULL AS COURIER, NULL AS CUSTOMER_NAME, NULL AS EMAIL, NULL AS phone, \'Flipkart\' AS MARKETPLACE, NULL AS MARKETPLACE_ID, \"Order ID\" as order_id, \"Order Item ID\"::VARCHAR AS SUBORDER_Id, \"Buyer Invoice ID\"::VARCHAR AS INVOICE_ID, \"Order ID\" AS REFERENCE_CODE, NULL AS MANIFEST_DATE, NULL AS SHIPPING_LAST_UPDATE_DATE, NULL AS SHIPPING_STATUS, (REGEXP_REPLACE(SUBSTRING(B.SKU, 8, 18), \'[^a-zA-Z0-9_-]\', \'\'))::VARCHAR SKU, NULL AS SKU_TYPE, marketplace_sku AS PRODUCT_ID, S.PRODUCT_NAME::VARCHAR AS PRODUCTNAME, NULL AS CURRENCY, NULL AS IS_REFUND, NULL AS CITY, \"Customer\'s Delivery State\" AS STATE, case when lower(\"Event Type\") like \'%cancel%\' then \'cancelled\' when lower(\"Event Type\") like \'%sale%\' then \'delivered\' when lower(\"Event Type\") like \'%return%\' then \'RTO\' else \"Event Type\" end AS ORDER_STATUS, try_TO_TIMESTAMP(replace(b.\"Order Date\",\'/\',\'-\'), \'YYYY-MM-DD HH24:MI:SS.FF\')::date AS order_date, try_TO_TIMESTAMP(replace(b.\"Order Date\",\'/\',\'-\'), \'YYYY-MM-DD HH24:MI:SS.FF\')::date AS order_timestamp, try_cast(\"Shipping Charges\" as int ) shipping_charges, NULL AS NUMBER_OF_PRODUCTS_IN_COMBO, try_cast(\"Item Quantity\" as int) AS suborder_quantity, null as SHIPPED_QUANTITY, NULL AS RETURNED_QUANTITY, NULL AS CANCELLED_QUANTITY, NULL AS RETURN_SALES, NULL AS CANCEL_SALES, (coalesce(eef.SELLING_PRICE,try_cast(\"Price before discount\" as float)) /1.13) as tax , null AS SUBORDER_MRP, UPPER(S.Category) AS category, UPPER(S.PRODUCT_NAME) AS Product_Name_Mapped, null AS Report_Category, null AS Product_Pack, try_cast(\"Item Quantity\" as int) AS Product_quantity, try_Cast(\"Total Discount\" as float) AS DISCOUNT, coalesce(eef.SELLING_PRICE,try_cast(\"Price before discount\" as float)) as selling_price, null AS MRP_SALES, try_cast(\"Total Discount\" as int) AS DISCOUNT_MRP, NULL AS NEW_CUSTOMER_FLAG, NULL AS NEW_CUSTOMER_FLAG_MONTH, null AS WAREHOUSE_NAME, NULL AS RETURN_FLAG, NULL AS DAYS_IN_SHIPMENT, NULL AS CHANNEL, NULL AS Shopify_UTM_source, NULL AS Shopify_UTM_Medium, NULL AS UTM_CAMPAIGN, coalesce(\"Order Type\",EEF.payment_mode) AS PAYMENT_MODE, NULL AS IMPORT_DATE, NULL AS LAST_UPDATE_DATE, null AS invoice_date, NULL AS company_name, \"Customer\'s Delivery Pincode\" AS pin_code, NULL AS FINAL_UTM_CAMPAIGN, \'Synced\' AS EasyEcom_Sync_Flag, CASE WHEN cancel_sales IS NOT NULL THEN LAST_UPDATE_DATE END AS cancelled_at, \'Meesho\' AS Data_Source ,s.sku as exception_sku FROM rpsg_db.maplemonk.ecom_flipkart_seller_report b LEFT JOIN ( select * from rpsg_DB.maplemonk.fact_items_easyecom_drv qualify row_number() over(partition by lower(reference_code),lower(sku) order by 1) = 1 )eef ON (b.\"Order ID\") = EEF.reference_code AND (LOWER(REGEXP_REPLACE(SUBSTRING(B.SKU, 8, 18), \'[^a-zA-Z0-9_-]\', \'\'))) = LOWER(EEF.SKU) INNER JOIN ( select * from (select SKU, BRAND, CATEGORY, MARKETPLACE, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, row_number() over (partition by lower(sku) order by 1) rw from rpsg_db.maplemonk.amazon_asin_amazon_asin where sku is not null ) where rw=1 ) S ON (LOWER(REGEXP_REPLACE(SUBSTRING(B.SKU, 8, 18), \'[^a-zA-Z0-9_-]\', \'\'))) = (LOWER(S.sku)); ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from RPSG_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            